// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.commonimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.Dispatchers/** * NOUS — Dispatcher qualifiers. * * Each bounded dispatcher has a Hilt qualifier so features can inject exactly * the one they need. This prevents "everyone uses Dispatchers.IO" antipattern. * * Provided by [com.roshan.persona.di.DispatcherModule] in :core:di. */// ─── Annotation qualifiers (Hilt) ───────────────────────────────────────────/** General-purpose I/O dispatcher (file, DB, network). */@javax.inject.Qualifier@Retention(AnnotationRetention.BINARY)annotation class IoDispatcher/** CPU-bound work dispatcher (default = CPU cores). */@javax.inject.Qualifier@Retention(AnnotationRetention.BINARY)annotation class DefaultDispatcher/** Main thread dispatcher with immediate dispatch. */@javax.inject.Qualifier@Retention(AnnotationRetention.BINARY)annotation class MainImmediateDispatcher/** LLM inference dispatcher (single-threaded, low priority). */@javax.inject.Qualifier@Retention(AnnotationRetention.BINARY)annotation class LlmDispatcher/** Computer vision dispatcher (MediaPipe / ML Kit). */@javax.inject.Qualifier@Retention(AnnotationRetention.BINARY)annotation class CvDispatcher/** Audio pipeline dispatcher (no double-record). */@javax.inject.Qualifier@Retention(AnnotationRetention.BINARY)annotation class AudioDispatcher/** * Convenience extension — get the underlying [CoroutineDispatcher] from the * Android [Dispatchers] object by name. Used by [DispatcherModule] only. */internal object DispatchersByName {    val io get() = Dispatchers.IO    val default get() = Dispatchers.Default    val mainImmediate get() = Dispatchers.Main.immediate}